import time
import random

def construct():
    start_time = time.time()
    deadline = 110.0 # 10s margin
    
    # Seed n=9
    n = 9
    colors = [min(j - i, n - j + i) - 1 for i in range(n) for j in range(i + 1, n)]
    
    # Helper to get color of edge (i, j)
    # Index for (i, j) in lexicographic order
    # Total edges for n vertices: n*(n-1)/2
    # Index of (i, j) where i < j:
    # Sum_{k=0}^{i-1} (n-1-k) + (j-i-1)
    # Wait, the list is generated by:
    # for i in range(n):
    #   for j in range(i+1, n):
    # So index = sum_{k=0}^{i-1} (n-1-k) + (j-i-1)
    
    def get_idx(n, i, j):
        # Number of edges for vertices 0..i-1
        # Vertex 0: n-1 edges
        # Vertex 1: n-2 edges
        # ...
        # Vertex i-1: n-i edges
        # Sum = i*n - i*(i+1)/2
        # Then edges from i to 0..j-1? No, i to j is the (j-i)-th edge from i (0-indexed j-i-1)
        return i * n - i * (i + 1) // 2 + (j - i - 1)

    def get_color(colors, n, i, j):
        if i > j: i, j = j, i
        return colors[get_idx(n, i, j)]

    def set_color(colors, n, i, j, c):
        if i > j: i, j = j, i
        colors[get_idx(n, i, j)] = c

    # Function to compute Bad_c matrices for current n and colors
    def compute_bad_matrices(n, colors):
        bad = [ [[False]*n for _ in range(n)] for _ in range(4) ]
        
        # Precompute neighbor sets for each color
        # neighbors[c][v] = set of u such that color(v,u) == c
        neighbors = [ [set() for _ in range(n)] for _ in range(4) ]
        
        for i in range(n):
            for j in range(i+1, n):
                c = get_color(colors, n, i, j)
                neighbors[c][i].add(j)
                neighbors[c][j].add(i)
                
        for c in range(4):
            for i in range(n):
                for j in range(i+1, n):
                    # Check if there is a path of length 4 in color c from i to j
                    # i - v1 - v2 - v3 - j
                    # v2 must be distinct from i, j
                    # v1 in N(i) \cap N(v2) \ {j}
                    # v3 in N(v2) \cap N(j) \ {i}
                    # and v1 != v3
                    
                    found = False
                    for v2 in range(n):
                        if v2 == i or v2 == j:
                            continue
                        A = neighbors[c][i] & neighbors[c][v2]
                        A.discard(j)
                        B = neighbors[c][v2] & neighbors[c][j]
                        B.discard(i)
                        
                        if not A or not B:
                            continue
                        
                        # Check if we can pick v1 in A, v3 in B such that v1 != v3
                        # If A and B are not identical singletons, we are good
                        if len(A) > 1 or len(B) > 1:
                            found = True
                            break
                        else:
                            # A and B are singletons
                            if A != B:
                                found = True
                                break
                    if found:
                        bad[c][i][j] = True
                        bad[c][j][i] = True
                        
        return bad

    # CSP Solver for extending n to n+1
    def try_extend(n, colors):
        if time.time() > deadline:
            return None
            
        bad = compute_bad_matrices(n, colors)
        
        # We need to assign colors to edges (v, n) for v in 0..n-1
        # Let new_colors[v] be the color of edge (v, n)
        # Constraint: For each c, the set {v | new_colors[v] == c} must be independent in graph (V, bad[c])
        # i.e., if new_colors[v] == c and new_colors[u] == c, then bad[c][v][u] must be False.
        
        # Backtracking on v = 0..n-1
        assignment = [-1] * n
        domains = [ [0,1,2,3] for _ in range(n) ]
        
        # Order vertices by degree in bad graphs?
        # Just use 0..n-1 for simplicity, or shuffle for random restarts
        order = list(range(n))
        
        def backtrack(idx):
            if time.time() > deadline:
                return False
            if idx == n:
                return True
                
            v = order[idx]
            
            # Forward checking: for each possible color c, check against already assigned vertices
            possible_colors = []
            for c in domains[v]:
                valid = True
                for u in order[:idx]:
                    if assignment[u] == c:
                        if bad[c][v][u]:
                            valid = False
                            break
                if valid:
                    possible_colors.append(c)
                    
            if not possible_colors:
                return False
                
            # Try colors
            # Heuristic: try color that causes least conflicts? Or random
            random.shuffle(possible_colors)
            for c in possible_colors:
                assignment[v] = c
                if backtrack(idx + 1):
                    return True
                assignment[v] = -1
                
            return False
            
        # Try a few random orderings if first fails?
        # For now, try once with natural order
        if backtrack(0):
            # Update colors list
            new_colors = colors[:]
            for v in range(n):
                new_colors.append(assignment[v])
            return new_colors
        return None

    # Main loop
    best_n = n
    best_colors = colors
    
    for target_n in range(10, 21):
        if time.time() > deadline:
            break
            
        # Try to extend from current n to target_n
        # Note: if we fail at n=10, we might want to try different starting points?
        # But for now, we just try to extend the current best.
        # If we fail, we break? Or try random restarts for the extension?
        
        success = False
        for attempt in range(10):
            if time.time() > deadline:
                break
            # If attempt > 0, we could shuffle the order in try_extend
            # Let's modify try_extend to accept a seed or shuffle order
            # For simplicity, we just call try_extend. If it fails, we break.
            # To improve success rate, we can randomize the order of vertices in try_extend.
            
            # Let's implement a version of try_extend that shuffles order
            def try_extend_random(n, colors, seed=None):
                if seed is not None:
                    random.seed(seed)
                bad = compute_bad_matrices(n, colors)
                assignment = [-1] * n
                domains = [ [0,1,2,3] for _ in range(n) ]
                order = list(range(n))
                random.shuffle(order)
                
                def backtrack(idx):
                    if time.time() > deadline:
                        return False
                    if idx == n:
                        return True
                    v = order[idx]
                    possible_colors = []
                    for c in domains[v]:
                        valid = True
                        for u in order[:idx]:
                            if assignment[u] == c:
                                if bad[c][v][u]:
                                    valid = False
                                    break
                        if valid:
                            possible_colors.append(c)
                    if not possible_colors:
                        return False
                    random.shuffle(possible_colors)
                    for c in possible_colors:
                        assignment[v] = c
                        if backtrack(idx + 1):
                            return True
                        assignment[v] = -1
                    return False
                    
                if backtrack(0):
                    new_colors = colors[:]
                    for v in range(n):
                        new_colors.append(assignment[v])
                    return new_colors
                return None

            res = try_extend_random(n, colors, seed=attempt)
            if res is not None:
                colors = res
                n = target_n
                best_n = n
                best_colors = colors
                success = True
                break
                
        if not success:
            # Try a few more random restarts for the failed n?
            # If we fail to extend, we stop.
            break

    return {'n': best_n, 'colors': best_colors}
